// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {TokenUtils} from "src/utils/vendor/0xSplits/TokenUtils.sol";

/// @dev Minimal ERC20 mock exposing decimals(), balanceOf() and a standard
/// transfer() that SafeTransferLib's low-level call path can interact with.
contract MockERC20 {
    string public name = "Mock Token";
    string public symbol = "MOCK";

    uint8 private immutable _decimalsValue;

    mapping(address => uint256) public balanceOf;

    constructor(uint8 decimals_) {
        _decimalsValue = decimals_;
    }

    function decimals() external view returns (uint8) {
        return _decimalsValue;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount; // reverts on underflow (insufficient balance)
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev A contract with neither `receive` nor `fallback`, used to force
/// SafeTransferLib's ETH transfer to fail.
contract RejectETH {}

contract TokenUtilsTest is Test {
    using TokenUtils for address;

    MockERC20 internal token;
    RejectETH internal rejectETH;

    address internal bob = makeAddr("bob");
    address internal alice = makeAddr("alice");

    receive() external payable {}

    function setUp() public {
        token = new MockERC20(18);
        rejectETH = new RejectETH();

        vm.deal(address(this), 100 ether);
        token.mint(address(this), 1_000e18);
    }

    /* -------------------------------------------------------------------- */
    /*                                _isETH                                */
    /* -------------------------------------------------------------------- */

    function test_ethAddressConstant() public pure {
        assertEq(TokenUtils.ETH_ADDRESS, address(0));
    }

    function test_isETH_trueForZeroAddress() public pure {
        assertTrue(TokenUtils._isETH(address(0)));
    }

    function test_isETH_falseForErc20() public view {
        assertFalse(TokenUtils._isETH(address(token)));
    }

    function testFuzz_isETH(address addr) public pure {
        assertEq(TokenUtils._isETH(addr), addr == address(0));
    }

    /* -------------------------------------------------------------------- */
    /*                               _decimals                              */
    /* -------------------------------------------------------------------- */

    function test_decimals_eth() public pure {
        assertEq(TokenUtils._decimals(address(0)), 18);
    }

    function test_decimals_erc20() public view {
        assertEq(TokenUtils._decimals(address(token)), 18);
    }

    function testFuzz_decimals_erc20(uint8 decimalsValue) public {
        MockERC20 customToken = new MockERC20(decimalsValue);
        assertEq(TokenUtils._decimals(address(customToken)), decimalsValue);
    }

    /* -------------------------------------------------------------------- */
    /*                              _balanceOf                              */
    /* -------------------------------------------------------------------- */

    function test_balanceOf_eth() public {
        assertEq(TokenUtils._balanceOf(address(0), address(this)), address(this).balance);

        vm.deal(alice, 5 ether);
        assertEq(TokenUtils._balanceOf(address(0), alice), 5 ether);
    }

    function test_balanceOf_erc20() public {
        assertEq(TokenUtils._balanceOf(address(token), address(this)), token.balanceOf(address(this)));

        token.mint(bob, 42e18);
        assertEq(TokenUtils._balanceOf(address(token), bob), 42e18);
    }

    function testFuzz_balanceOf_eth(uint96 amount) public {
        vm.deal(alice, amount);
        assertEq(TokenUtils._balanceOf(address(0), alice), amount);
    }

    function testFuzz_balanceOf_erc20(uint128 amount) public {
        token.mint(alice, amount);
        assertEq(TokenUtils._balanceOf(address(token), alice), token.balanceOf(alice));
    }

    /* -------------------------------------------------------------------- */
    /*                             _safeTransfer                            */
    /* -------------------------------------------------------------------- */

    function test_safeTransfer_eth() public {
        uint256 bobBalBefore = bob.balance;
        uint256 thisBalBefore = address(this).balance;

        TokenUtils._safeTransfer(address(0), bob, 1 ether);

        assertEq(bob.balance, bobBalBefore + 1 ether);
        assertEq(address(this).balance, thisBalBefore - 1 ether);
    }

    function test_safeTransfer_eth_zeroAmount() public {
        uint256 bobBalBefore = bob.balance;
        TokenUtils._safeTransfer(address(0), bob, 0);
        assertEq(bob.balance, bobBalBefore);
    }

    function test_safeTransfer_eth_revertsWhenRecipientCannotReceive() public {
        vm.expectRevert();
        TokenUtils._safeTransfer(address(0), address(rejectETH), 1 ether);
    }

    function test_safeTransfer_eth_revertsOnInsufficientBalance() public {
        vm.expectRevert();
        TokenUtils._safeTransfer(address(0), bob, address(this).balance + 1);
    }

    function test_safeTransfer_erc20() public {
        uint256 bobBalBefore = token.balanceOf(bob);
        uint256 thisBalBefore = token.balanceOf(address(this));

        TokenUtils._safeTransfer(address(token), bob, 100e18);

        assertEq(token.balanceOf(bob), bobBalBefore + 100e18);
        assertEq(token.balanceOf(address(this)), thisBalBefore - 100e18);
    }

    function test_safeTransfer_erc20_zeroAmount() public {
        uint256 bobBalBefore = token.balanceOf(bob);
        TokenUtils._safeTransfer(address(token), bob, 0);
        assertEq(token.balanceOf(bob), bobBalBefore);
    }

    function test_safeTransfer_erc20_revertsOnInsufficientBalance() public {
        uint256 tooMuch = token.balanceOf(address(this)) + 1;
        vm.expectRevert();
        TokenUtils._safeTransfer(address(token), bob, tooMuch);
    }

    function testFuzz_safeTransfer_eth(uint96 amount) public {
        amount = uint96(bound(amount, 0, 50 ether));
        vm.deal(address(this), amount);

        uint256 bobBalBefore = bob.balance;
        TokenUtils._safeTransfer(address(0), bob, amount);
        assertEq(bob.balance, bobBalBefore + amount);
    }

    function testFuzz_safeTransfer_erc20(uint128 amount) public {
        amount = uint128(bound(amount, 0, token.balanceOf(address(this))));

        uint256 bobBalBefore = token.balanceOf(bob);
        TokenUtils._safeTransfer(address(token), bob, amount);
        assertEq(token.balanceOf(bob), bobBalBefore + amount);
    }
}
