// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { ERC20SafeApproveLib } from "src/core/libs/ERC20SafeApproveLib.sol";
import { IMultistrategyVault } from "src/core/interfaces/IMultistrategyVault.sol";

/// @dev Standard-compliant ERC20 mock: approve() returns a proper bool.
contract MockERC20Standard {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
}

/// @dev USDT-like ERC20 mock: approve() does not return any data at all.
contract MockERC20NoReturn {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external {
        allowance[msg.sender][spender] = amount;
    }
}

/// @dev ERC20 mock whose approve() returns `false` instead of reverting on "failure".
contract MockERC20ReturnsFalse {
    function approve(address, uint256) external pure returns (bool) {
        return false;
    }
}

/// @dev ERC20 mock whose approve() always reverts.
contract MockERC20Reverts {
    function approve(address, uint256) external pure returns (bool) {
        revert("APPROVE_REVERTED");
    }
}

/// @dev ERC20 mock whose approve() returns malformed (too short) return data,
///      which cannot be abi.decode()'d as a bool.
contract MockERC20InvalidReturnData {
    fallback() external {
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x01)
            return(ptr, 1) // only 1 byte returned, not enough for a bool word
        }
    }
}

/// @dev ERC20 mock whose approve() returns `true` plus extra trailing return data.
///      abi.decode should still succeed by reading only the first word.
contract MockERC20ReturnsTrueWithExtraData {
    fallback() external {
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 1) // true
            mstore(add(ptr, 0x20), 0xdeadbeef) // extra garbage word
            return(ptr, 0x40)
        }
    }
}

/// @dev Harness contract so we can wrap `ERC20SafeApproveLib.safeApprove` calls
///      with `vm.expectRevert` / try-catch semantics conveniently and so the
///      library's external function gets properly linked/dispatched.
contract SafeApproveCaller {
    function callSafeApprove(address token, address spender, uint256 amount) external {
        ERC20SafeApproveLib.safeApprove(token, spender, amount);
    }
}

contract ERC20SafeApproveLibTest is Test {
    SafeApproveCaller internal caller;

    address internal spender = address(0xB0B);

    function setUp() public {
        caller = new SafeApproveCaller();
    }

    /* -------------------------------------------------------------------- */
    /*                           Happy path cases                           */
    /* -------------------------------------------------------------------- */

    function test_SafeApprove_StandardToken_SetsAllowance() public {
        MockERC20Standard token = new MockERC20Standard();

        caller.callSafeApprove(address(token), spender, 1_000e18);

        assertEq(token.allowance(address(caller), spender), 1_000e18);
    }

    function testFuzz_SafeApprove_StandardToken_SetsAllowance(uint256 amount, address fuzzSpender) public {
        MockERC20Standard token = new MockERC20Standard();

        caller.callSafeApprove(address(token), fuzzSpender, amount);

        assertEq(token.allowance(address(caller), fuzzSpender), amount);
    }

    function test_SafeApprove_NoReturnToken_Succeeds() public {
        MockERC20NoReturn token = new MockERC20NoReturn();

        caller.callSafeApprove(address(token), spender, 500e6);

        assertEq(token.allowance(address(caller), spender), 500e6);
    }

    function test_SafeApprove_ReturnsTrueWithExtraData_Succeeds() public {
        MockERC20ReturnsTrueWithExtraData token = new MockERC20ReturnsTrueWithExtraData();

        // Should not revert even though extra trailing data is returned.
        caller.callSafeApprove(address(token), spender, 42);
    }

    function test_SafeApprove_ZeroAmount_Succeeds() public {
        MockERC20Standard token = new MockERC20Standard();

