import { ERC20SafeApproveLib } from "src/core/libs/ERC20SafeApproveLib.sol";
import { IMultistrategyVault } from "src/core/interfaces/IMultistrategyVault.sol";

/// @dev Standard-compliant ERC20 mock: approve() returns bool as expected.
contract StandardERC20Mock {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
}

/// @dev Mock mimicking tokens (e.g. USDT) whose approve() returns no data at all.
contract NoReturnDataERC20Mock {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external {
        allowance[msg.sender][spender] = amount;
    }
}

/// @dev Mock whose approve() call succeeds but returns false, simulating a
///      non-reverting failure that safeApprove must catch.
contract FalseReturnERC20Mock {
    function approve(address, uint256) external pure returns (bool) {
        return false;
    }
}

contract ERC20SafeApproveLibTest is Test {
    address internal spender = address(0xBEEF);

    function test_SafeApproveSetsAllowanceOnStandardToken() public {
        StandardERC20Mock token = new StandardERC20Mock();

        ERC20SafeApproveLib.safeApprove(address(token), spender, 1_000e18);

        assertEq(token.allowance(address(this), spender), 1_000e18);
    }

    function test_SafeApproveSetsAllowanceWhenTokenReturnsNoData() public {
        NoReturnDataERC20Mock token = new NoReturnDataERC20Mock();

        ERC20SafeApproveLib.safeApprove(address(token), spender, 500e18);

        assertEq(token.allowance(address(this), spender), 500e18);
    }

    function test_SafeApproveRevertsWhenTokenReturnsFalse() public {
        FalseReturnERC20Mock token = new FalseReturnERC20Mock();

        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(token), spender, 1e18);
    }
}

